   section_start("", 274454803)!
   /*Dat:*/
   VAR_CONFIG = {
   BeforeRequest: {
   changeUrl: [{
   match: "https://www.example.com/BeforeRequest/",
   matchMode: "equals",
   to: "https://echo.free.beeceptor.com/BeforeRequest/"
   }]
   },
   AfterRequest: {
   retries: [{
   match: "/AfterRequest/",
   matchMode: "contains",
   maxAttempts: 10,
   retryUrl: "https://echo.free.beeceptor.com/AfterRequest/retries/",
   attemptParam: "q"
   }]
   },
   ErrorRequest: {
   ignoreErrors: [{
   match: "/ErrorRequest/",
   matchMode: "endswith",
   disableRetries: true
   }]
   }
   };
   function urlMatches(rule, url) {
   if (rule.matchMode === "startswith") {
   return url.indexOf(rule.match) === 0;
   }
   if (rule.matchMode === "endswith") {
   return rule.match.length <= url.length &&
   url.lastIndexOf(rule.match) === url.length - rule.match.length;
   }
   if (rule.matchMode === "contains") {
   return url.indexOf(rule.match) !== -1;
   }
   return url === rule.match;
   }
   function findUrlRule(rules, url) {
   if (!rules) return null;
   for (var i = 0; i < rules.length; i++) {
   if (urlMatches(rules[i], url)) {
   return rules[i];
   }
   }
   return null;
   }
   ImpersonateBeforeRequest = function() {
   var request = _function_argument("request");
   var retry = _function_argument("retry");
   var rule = findUrlRule(
   VAR_CONFIG.BeforeRequest.changeUrl,
   request.url
   );
   if (rule) {
   log(request.url + " : Changed to " + rule.to);
   request.url = rule.to;
   }
   _function_return({
   request: request,
   retry: retry
   });
   };
   ImpersonateAfterRequest = function() {
   var request = _function_argument("request");
   var retry = _function_argument("retry");
   // ImpersonateErrorRequest handles failed requests.
   if (impersonate.wasError()) {
   return;
   }
   var result;
   var rule = findUrlRule(
   VAR_CONFIG.AfterRequest.retries,
   request.url
   );
   if (rule) {
   if (retry.attempt < rule.maxAttempts) {
   var nextAttempt = retry.attempt + 1;
   result = false;
   log(
   request.url +
   " : Retrying | Attempt: " +
   nextAttempt +
   " / " +
   rule.maxAttempts
   );
   if (rule.retryUrl) {
   var retryUrl = impersonate.utils.parseUrl(rule.retryUrl);
   retryUrl.searchParams.set(
   rule.attemptParam,
   nextAttempt
   );
   request.url = retryUrl.toString();
   }
   } else {
   log_success(
   request.url +
   " : Done! Maximum number of attempts reached."
   );
   }
   }
   _function_return({
   request: request,
   retry: retry,
   result: result
   });
   };
   ImpersonateErrorRequest = function() {
   var request = _function_argument("request");
   var retry = _function_argument("retry");
   var result;
   var rule = findUrlRule(
   VAR_CONFIG.ErrorRequest.ignoreErrors,
   request.url
   );
   if (rule) {
   log(
   request.url +
   " : Ignored error | " +
   impersonate.lastError(true)
   );
   retry.failOnError = false;
   if (rule.disableRetries) {
   result = true;
   }
   }
   _function_return({
   request: request,
   retry: retry,
   result: result
   });
   };
   section_end()!

